package au.edu.uow.csci318.activity.controller;import au.edu.uow.csci318.activity.application.StudyActivityApplicationService;import au.edu.uow.csci318.activity.application.StudyActivityApplicationService.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/study-sessions") @CrossOrigin public class StudyActivityController{private final StudyActivityApplicationService service;public StudyActivityController(StudyActivityApplicationService s){service=s;}@PostMapping@ResponseStatus(HttpStatus.CREATED)public Response record(@Valid@RequestBody CreateRequest r){return service.record(r);}@GetMapping public List<Response>all(){return service.all();}@GetMapping("/summary")public Summary summary(@RequestParam UUID subjectId,@RequestParam(required=false)LocalDate weekOf){return service.summary(subjectId,weekOf);}}
